        V['ok_pid'] = pid
        V['ok_amount'] = str(float(a))
        V['ok_date'] = d.isoformat()
        V['offer_verdict'] = 'ok'
        set_prop(V, pid, a, d)
        if move:
            advance(V, '')
    def refuse(V, pid, prefix=''):
