    def to_amount(v):
        if isinstance(v, bool):
            return None
        if isinstance(v, (int, float)):
            return float(v)
        s = str(v).strip().lower()
        cents = 0.0
        m = re.fullmatch(r'(.*?)\s*(?:dollars?|pounds?|euros?|bucks)\s*(?:and\s+)?(.+?)\s*(?:cents?|pence)', s)
