        ids = pids(V)
        sts = [state(V, p) for p in ids]
        fk = P['fin_keys']
        if 'recorded' in sts:
            key = fk['promise']
        elif sts and all(s == 'paid' for s in sts):
            key = fk['paid']
        else:
            key = fk['default']
            for s in sts:
                if s != 'paid':
                    key = fk.get(s) or fk['default']
                    break
        V['final_route'] = key
        V['route'] = 'fin'
