            V['offer_question'] = T('question_all')
        V['say_next'] = statement
        V['route'] = 'negotiate'
        finish_turn(V)
    def readback(V, ids):
        items = []
        for p in ids:
            parts = pg(V, p, 'agreed').split('|')
            a = num(parts[0], 0.0) if parts else 0.0
            d = pdate(parts[1]) if len(parts) > 1 else None
            tag = parts[2] if len(parts) > 2 else ''
            if d is None:
                continue
            s = T('readback_item', words=pg(V, p, 'words'), amount=fmt(a), when=when(V, d), date=txt_short(d))
            if tag == 'dl':
                s += T('own_deadline')
            elif tag == 'bd':
                s += T('moved_bd')
            items.append(s)
        return T('readback_head') + T('readback_sep').join(items) + T('readback_tail')
    def start_product(V, pid, prefix):
        V['stage'] = 'one'
        V['cur_pid'] = pid
        if not ladder(V, pid):
            a, d = full_of(V, pid), deadline_of(V, pid)
        else:
            a, d = rung(V, pid, 0)
            pset(V, pid, 'attempts_used', 1)
        set_prop(V, pid, a, d)
        say(V, join([prefix, T('next_product', words=pg(V, pid, 'words'), past_due=fmt(full_of(V, pid))), V['offer_question']]), 'negotiate')
    def advance(V, prefix=''):
        ids = pids(V)
        opn = [p for p in ids if state(V, p) == 'open']
        if opn and g(V, 'mode') == 'hardship':
            for p in opn:
                pset(V, p, 'state', 'hardship')
            opn = []
        if opn:
            start_product(V, opn[0], prefix)
            return
        agreed = [p for p in ids if state(V, p) == 'agreed']
        if agreed:
            V['readback_line'] = join([prefix, readback(V, agreed)])
            V['route'] = 'confirm'
            return
        note_next(V)
    def agree(V, pid, a, d, tag='', move=True):
        pset(V, pid, 'state', 'agreed')
        pset(V, pid, 'agreed', str(float(a)) + '|' + d.isoformat() + '|' + tag)
        V['ok_pid'] = pid
        V['ok_amount'] = str(float(a))
        V['ok_date'] = d.isoformat()
        V['offer_verdict'] = 'ok'
        set_prop(V, pid, a, d)
        if move:
            advance(V, '')
    def refuse(V, pid, prefix=''):
        if g(V, 'mode') == 'hardship':
            pset(V, pid, 'state', 'hardship')
            advance(V, '')
            return
        a0, d0 = prop_of(V, pid)
        rl = refused_list(V, pid)
        if okey(a0, d0) not in rl:
            rl.append(okey(a0, d0))
        pset(V, pid, 'refused_offers', ';'.join(rl))
        L = ladder(V, pid)
        k = int(num(pg(V, pid, 'attempts_used'), 0) or 0)
        while k < len(L):
            a, d = rung(V, pid, k)
            if okey(a, d) not in rl:
                break
            k += 1
        if k >= len(L):
            pset(V, pid, 'state', 'refused')
            V['offer_verdict'] = 'exhausted'
            advance(V, join([prefix, T('exhausted')]))
            return
        pset(V, pid, 'attempts_used', k + 1)
        set_prop(V, pid, a, d)
        V['next_offer_text'] = V['offer_question']
        say(V, join([prefix, V['offer_question']]), 'negotiate')
    def too_much(V, pid, prefix=''):
        pset(V, pid, 'too_much', 'yes')
        a0, d0 = prop_of(V, pid)
        fl_ = floor_of(V, pid)
        if g(V, 'mode') != 'hardship' and pg(V, pid, 'offered_floor') != 'yes' and fl_ < a0 - 0.005:
            pset(V, pid, 'offered_floor', 'yes')
            set_prop(V, pid, fl_, d0)
            say(V, join([prefix, T('too_much_floor', floor=fmt(fl_), floor_name=pg(V, pid, 'floor_name'), words=pg(V, pid, 'words')), V['offer_question']]))
            return
        refuse(V, pid, prefix)
    def check_one(V, pid, a, d, kind):
        n = int(num(pg(V, pid, 'checks'), 0) or 0) + 1
        pset(V, pid, 'checks', n)
        if n > int(P['max_checks']):
            pset(V, pid, 'state', 'hardship' if g(V, 'mode') == 'hardship' else 'refused')
            V['offer_verdict'] = 'loop_exhausted'
            advance(V, T('exhausted'))
            return
        pa, pd = prop_of(V, pid)
        t = today_of(V)
        dl = deadline_of(V, pid)
        if kind == 'vague' or (a is None and d is None):
            V['offer_verdict'] = 'vague'
            if pg(V, pid, 'vague_asked') != 'yes':
                pset(V, pid, 'vague_asked', 'yes')
                say(V, T('vague'))
                return
            set_prop(V, pid, pa, dl)
            say(V, join([T('vague_deadline', deadline=txt_short(dl), words=pg(V, pid, 'words')), V['offer_question']]))
            return
        amt = pa if a is None else a
        day = pd if d is None else d
        issues = []
        na, nd = amt, day
        if nd < t:
            issues.append(('before_today', T('before_today', named=txt_short(nd))))
            nd = t if isbd(t) else next_bd(t)
        elif nd > dl:
            issues.append(('after_deadline', T('after_deadline', deadline=txt_short(dl), named=txt_short(nd), words=pg(V, pid, 'words'))))
            nd = dl
        elif not isbd(nd):
            nb = next_bd(nd)
            if P['closed_day_move'] == 'before':
                nb = prev_bd(nd)
                if nb < t:
                    nb = next_bd(nd)
            if nb > dl:
                nb = dl
            issues.append(('weekend_or_holiday', T('weekend_or_holiday', named=txt_short(nd), date=txt_short(nb))))
            nd = nb
        fl_ = floor_of(V, pid)
        full = full_of(V, pid)
        if na < fl_ - 0.005:
            if pg(V, pid, 'offered_floor') == 'yes' and g(V, 'mode') != 'hardship':
                V['offer_verdict'] = 'below_floor'
                refuse(V, pid)
                return
            issues.append(('below_floor', T('below_floor', named=fmt(na), floor=fmt(fl_), floor_name=pg(V, pid, 'floor_name'), words=pg(V, pid, 'words'))))
            pset(V, pid, 'offered_floor', 'yes')
            na = fl_
        elif na > full + 0.005:
            issues.append(('above_full', T('above_full', full=fmt(full), named=fmt(na), words=pg(V, pid, 'words'))))
            na = full
        if not issues:
            agree(V, pid, na, nd)
            return
        V['offer_verdict'] = issues[0][0]
        set_prop(V, pid, na, nd)
        V['offer_text'] = join([x[1] for x in issues] + [V['offer_question']])
        say(V, V['offer_text'])
    def offer_target(V):
        f = g(V, 'offer_for')
        ids = pids(V)
        order = P['ordinals']
        if f in order:
            i = order.index(f)
            if i < len(ids):
                return ids[i]
        return ''
    def all_offer(V, d):
        t = today_of(V)
        for p in [x for x in pids(V) if state(V, x) == 'open']:
            dd = d
            tag = ''
            dl = deadline_of(V, p)
            if dd < t:
                dd = t if isbd(t) else next_bd(t)
            if not isbd(dd):
                dd = next_bd(dd)
                tag = 'bd'
            if dd > dl:
                dd = dl
                tag = 'dl'
            agree(V, p, full_of(V, p), dd, tag, move=False)
        V['offer_verdict'] = 'ok'
        advance(V, '')
    WDN = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
    MON = {'january': 1, 'february': 2, 'march': 3, 'april': 4, 'may': 5, 'june': 6, 'july': 7, 'august': 8,
           'september': 9, 'october': 10, 'november': 11, 'december': 12}
    NUMW = {'a': 1, 'an': 1, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8,
            'nine': 9, 'ten': 10, 'fourteen': 14}
    def _month_of(w):
        for k, v in MON.items():
            if w.startswith(k[:3]):
                return v
        return None
    ORDW = {'first': 1, 'second': 2, 'third': 3, 'fourth': 4, 'fifth': 5, 'sixth': 6, 'seventh': 7, 'eighth': 8, 'ninth': 9,
            'tenth': 10, 'eleventh': 11, 'twelfth': 12, 'thirteenth': 13, 'fourteenth': 14, 'fifteenth': 15, 'sixteenth': 16,
            'seventeenth': 17, 'eighteenth': 18, 'nineteenth': 19, 'twentieth': 20, 'thirtieth': 30}
    def _ordinal_words(t):
        for tens, base in (('twenty', 20), ('thirty', 30)):
            for w, n in ORDW.items():
                if n < 10:
                    t = t.replace(' %s %s ' % (tens, w), ' %dth ' % (base + n))
        for w in sorted(ORDW, key=len, reverse=True):
            t = t.replace(' %s ' % w, ' %dth ' % ORDW[w])
        return t
    def resolve_when(V, text):
        # (date, kind) from the customer's OWN WORDS, relative to the call's today (never the real clock: the platform's
        # date extraction resolved 'tomorrow' with the real clock). kind: 'exact' (with a date), 'vague', or 'none'.
        t = ' ' + re.sub(r'[^a-z0-9 ]', ' ', str(text or '').lower()) + ' '
        t = _ordinal_words(re.sub(r'\s+', ' ', t))
        if not t.strip():
            return None, 'none'
        today = today_of(V)
        D = datetime.timedelta
        if re.search(r' (twenty|thirty) $', t):
            # the words stop on a bare tens word ('I can pay on the twenty'): a cut-off day, never the 20th or the 30th
            # and never the extractor's guess (Freya talkative PUB-04 recorded the 20th for 'the twenty[-third]')
            return None, 'vague'
        if ' day after tomorrow ' in t:
            return today + D(2), 'exact'
        if ' tomorrow ' in t:
            return today + D(1), 'exact'
        if re.search(r' (today|tonight|right now|now|this morning|this afternoon|this evening) ', t):
            return today, 'exact'
        m = re.search(r' in (\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten|fourteen) (day|week|fortnight)s? ', t)
        if m:
            n = int(m.group(1)) if m.group(1).isdigit() else NUMW.get(m.group(1), 1)
            n = n * (7 if m.group(2) == 'week' else 14 if m.group(2) == 'fortnight' else 1)
            return today + D(n), 'exact'
        m = re.search(r' (\d{1,2})(?:st|nd|rd|th)? (?:of )?([a-z]{3,9})(?: (\d{4}))? ', t)
        mo = _month_of(m.group(2)) if m else None
        if m and mo:
            y = int(m.group(3)) if m.group(3) else today.year
            try:
                d = datetime.date(y, mo, int(m.group(1)))
                if not m.group(3) and d < today - D(14):
                    d = datetime.date(y + 1, mo, int(m.group(1)))
                return d, 'exact'
            except Exception:
                return None, 'vague'
        m = re.search(r' ([a-z]{3,9}) (?:the )?(\d{1,2})(?:st|nd|rd|th)? ', t)
        mo = _month_of(m.group(1)) if m else None
        if m and mo:
            try:
                d = datetime.date(today.year, mo, int(m.group(2)))
                if d < today - D(14):
                    d = datetime.date(today.year + 1, mo, int(m.group(2)))
                return d, 'exact'
            except Exception:
                return None, 'vague'
        # a day of the month wins over a weekday said with it ('Monday the twenty-sixth' is the 26th, never the next
        # Monday): the read-back then names the date's real weekday, so a mismatch is the customer's to correct
        m = (re.search(r' (?:monday|tuesday|wednesday|thursday|friday|saturday|sunday) (?:the )?(\d{1,2})(?:st|nd|rd|th)? ', t)
             or re.search(r' (?:the )?(\d{1,2})(?:st|nd|rd|th) ', t))
        if m:
            n = int(m.group(1))
            y, mo = today.year, today.month
            if n < today.day:
                mo += 1
                if mo > 12:
                    mo, y = 1, y + 1
            try:
                return datetime.date(y, mo, n), 'exact'
            except Exception:
                return None, 'vague'
        # weekdays LAST: 'Monday the 26th' is the 26th (the number wins; PUB-07 looped on 'Monday 19 October' when the weekday matched first)
        m = re.search(r' (?:(this|next|coming|on|by) )?(monday|tuesday|wednesday|thursday|friday|saturday|sunday) ', t)
        if m:
            wd = WDN.index(m.group(2))
            if m.group(1) == 'next':
                if P.get('weekday_rule') == 'first_after':
                    delta = (wd - today.weekday()) if ' this ' in t else (wd - today.weekday()) % 7 or 7
                else:   # that weekday in the following calendar week
                    delta = (7 - today.weekday()) + wd
            else:
                delta = (wd - today.weekday()) if ' this ' in t else (wd - today.weekday()) % 7
            return today + D(delta), 'exact'
        if re.search(r'(next week|week after next|end of (the )?month|end of month|this month|next month|when (my |the )?(salary|pay|wages|money)|'
                     r'after (my |the )?(pay|salary)|a few (days|weeks)|couple of (days|weeks)|soon|later|some ?time|not sure|maybe|'
                     r'next (few|couple)|beginning of|middle of|start of|mid )', t):
            return None, 'vague'
        return None, 'none'
    def offer_date_of(V):
        # the customer's words first (offer_when, resolved in code); the extraction's offer_date only as a fallback and
        # never a date before the call's today
        d, kind = resolve_when(V, g(V, 'offer_when'))
        if kind == 'exact' and d is not None:
            return d, 'exact'
        if kind == 'vague':
            return None, 'vague'
        d = pdate(g(V, 'offer_date'))
        if d is not None and d < today_of(V):
            return None, 'vague'
        return d, g(V, 'offer_kind')
    def ev_offer(V):
        kind = g(V, 'offer_kind')
        a = num(g(V, 'offer_amount'))
        if a is not None and a <= 0:
            a = None
        d, k2 = offer_date_of(V)
        if k2 in ('exact', 'vague'):
            kind = k2
        if kind == 'vague':
            d = None
        if multi(V) and g(V, 'stage') != 'all' and g(V, 'offer_for') == 'all' and d is not None and a is None and kind == 'exact':
            all_offer(V, d)
            return
        if multi(V) and g(V, 'stage') == 'all':
            tp = offer_target(V)
            if tp:
                V['stage'] = 'one'
                V['cur_pid'] = tp
                check_one(V, tp, a, d, kind)
                return
            if kind == 'vague' or (d is None and a is None):
                V['offer_verdict'] = 'vague'
                if g(V, 'vague_all') != 'yes':
                    V['vague_all'] = 'yes'
                    say(V, T('vague'))
                    return
                p = pids(V)[0]
                pset(V, p, 'vague_asked', 'yes')
                V['stage'] = 'one'
                V['cur_pid'] = p
                check_one(V, p, None, None, 'vague')
                return
            if d is not None and g(V, 'offer_for') == 'all':
                all_offer(V, d)
                return
            if d is not None:
                # A date by itself does not establish consent for every product.
                # Clarify one product at a time when scope was not extracted.
                start_product(V, pids(V)[0], T('one_by_one'))
                return
            p = pids(V)[0]
            V['stage'] = 'one'
            V['cur_pid'] = p
            check_one(V, p, a, None, 'exact')
            return
        check_one(V, g(V, 'cur_pid'), a, d, kind)
    def ev_accept(V):
        if multi(V) and g(V, 'stage') == 'all':
            t = today_of(V)
            tp = offer_target(V)
            if tp:
                agree(V, tp, full_of(V, tp), t if isbd(t) else next_bd(t))
                return
            for p in [x for x in pids(V) if state(V, x) == 'open']:
                agree(V, p, full_of(V, p), t if isbd(t) else next_bd(t), '', move=False)
            advance(V, '')
            return
        pid = g(V, 'cur_pid')
        if state(V, pid) == 'agreed':
            pset(V, pid, 'state', 'open')
        a, d = prop_of(V, pid)
        check_one(V, pid, a, d, 'exact')
    def to_one_by_one(V):
        p = pids(V)[0]
        V['stage'] = 'one'
        V['cur_pid'] = p
        return p, join([T('one_by_one'), T('next_product', words=pg(V, p, 'words'), past_due=fmt(full_of(V, p)))])
    def ev_refuse(V):
        if multi(V) and g(V, 'stage') == 'all':
            p, pre = to_one_by_one(V)
            refuse(V, p, pre)
            return
        pid = g(V, 'cur_pid')
        if state(V, pid) == 'agreed':
            pset(V, pid, 'state', 'open')
        refuse(V, pid)
    def ev_too_much(V):
        if multi(V) and g(V, 'stage') == 'all':
            p, pre = to_one_by_one(V)
            too_much(V, p, pre)
            return
        too_much(V, g(V, 'cur_pid'))
    def targets_for_topic(V):
        tp = offer_target(V)
        if tp:
            return [tp]
        if multi(V) and g(V, 'stage') == 'all':
            return [p for p in pids(V) if state(V, p) in ('open', 'agreed')]
        return [g(V, 'cur_pid')]
    def ev_settle(V, kind):
        ts = targets_for_topic(V)
        words = [pg(V, p, 'words') for p in ts]
        for p in ts:
            pset(V, p, 'state', kind)
        pre = T(kind, words=T('and').join(words)) if multi(V) else ''
        advance(V, pre)
    def ev_human(V):
        c = int(num(g(V, 'human_count'), 0) or 0) + 1
        V['human_count'] = str(c)
        if c >= int(P['human_limit']):
            V['route'] = 'xfer_general'
            return
        say(V, T('human_first'))
    def ev_notalk(V):
        c = int(num(g(V, 'notalk_count'), 0) or 0) + 1
        V['notalk_count'] = str(c)
        if c >= int(P['notalk_limit']):
            for p in pids(V):
                if state(V, p) in ('open', 'agreed'):
                    pset(V, p, 'state', 'refused')
            advance(V, '')
            return
        say(V, join([T('notalk_first'), g(V, 'offer_question')]))
    def ev_hardship(V):
        V['mode'] = 'hardship'
        hd, hk = offer_date_of(V)
        if g(V, 'offer_kind') == 'exact' or hk == 'exact':
            V['hs_offer'] = 'yes'
            V['hs_date'] = hd.isoformat() if hd is not None else ''
            V['hs_amount'] = g(V, 'offer_amount')
        say(V, T('hardship'), 'hardship')
    def ev_hs_decline(V):
        if g(V, 'hs_offer') == 'yes':
            V['hs_offer'] = 'no'
            V['offer_kind'] = 'exact'
            V['offer_date'] = g(V, 'hs_date')
            V['offer_amount'] = g(V, 'hs_amount')
            ev_offer(V)
            return
        for p in pids(V):
            if state(V, p) == 'open':
                pset(V, p, 'state', 'hardship')
        advance(V, '')
    def ev_hs_offer(V):
        ev_offer(V)
    def ev_confirm_no(V):
        agreed = [p for p in pids(V) if state(V, p) == 'agreed']
        pid = g(V, 'cur_pid') if g(V, 'cur_pid') in agreed else (agreed[-1] if agreed else g(V, 'cur_pid'))
        V['cur_pid'] = pid
        V['stage'] = 'one'
        parts = pg(V, pid, 'agreed').split('|')
        a = num(parts[0]) if parts else None
        d = pdate(parts[1]) if len(parts) > 1 else None
        if a is not None and d is not None:
            set_prop(V, pid, a, d)
        pset(V, pid, 'state', 'open')
        refuse(V, pid)
    def ev_change(V):
        agreed = [p for p in pids(V) if state(V, p) == 'agreed']
        a = num(g(V, 'offer_amount'))
        if a is not None and a <= 0:
            a = None
        d, k2 = offer_date_of(V)
        tp = offer_target(V)
        if tp and multi(V):
            # A correction/partial confirmation withdraws the other unrecorded
            # agreements; negotiate them again rather than silently recording them.
            for p in agreed:
                if p != tp:
                    pset(V, p, 'state', 'open')
                    pset(V, p, 'agreed', '')
        if not tp and multi(V) and len(agreed) > 1 and d is not None and a is None:
            for p in agreed:
                pset(V, p, 'state', 'open')
            all_offer(V, d)
            return
        pid = tp or (g(V, 'cur_pid') if g(V, 'cur_pid') in agreed else (agreed[-1] if agreed else g(V, 'cur_pid')))
        parts = pg(V, pid, 'agreed').split('|')
        pa = num(parts[0]) if parts else None
        pd = pdate(parts[1]) if len(parts) > 1 else None
        if pa is not None and pd is not None:
            set_prop(V, pid, pa, pd)
        pset(V, pid, 'state', 'open')
        V['cur_pid'] = pid
        V['stage'] = 'one'
        pset(V, pid, 'checks', 0)
        check_one(V, pid, a, d, 'exact')
    def rec_next(V):
        for p in pids(V):
            if state(V, p) == 'agreed':
                parts = pg(V, p, 'agreed').split('|')
                V['rec_pid'] = p
                V['rec_amount'] = str(num(parts[0], 0.0))
                V['rec_date'] = parts[1] if len(parts) > 1 else ''
                V['rec_ok'] = 'pending'
                V['route'] = 'record'
                return
        note_next(V)
    def ev_confirm_yes(V):
        tp = offer_target(V)
        if multi(V) and tp and any(state(V, p) == 'agreed' for p in pids(V) if p != tp):
            ev_change(V)
            return
        rec_next(V)
    def ev_rec_after(V):
        p = g(V, 'rec_pid')
        ok = g(V, 'rec_ok').lower() == 'true'
        if p:
            if ok:
                pset(V, p, 'state', 'recorded')
                rl = [x for x in g(V, 'recorded_pids').split(',') if x]
                if p not in rl:
                    rl.append(p)
                V['recorded_pids'] = ','.join(rl)
            else:
                f = int(num(pg(V, p, 'fails'), 0) or 0) + 1
                pset(V, p, 'fails', f)
                if f < int(P['fail_max']):
                    V['rec_ok'] = 'pending'
                    V['route'] = 'record'
                    return
                pset(V, p, 'state', 'service_error')
        rec_next(V)
    def note_next(V):
        if P['notes']:
            for p in pids(V):
                st = state(V, p)
                if st in P['note_reasons'] and pg(V, p, 'noted') == 'no':
                    V['note_pid'] = p
                    V['note_reason'] = P['note_reasons'][st]
                    V['note_ok'] = 'pending'
                    V['route'] = 'note'
                    return
        if [p for p in pids(V) if state(V, p) == 'recorded']:
            enter_wrapup(V)
            return
        finalize(V)
    def ev_note_after(V):
        p = g(V, 'note_pid')
        if p:
            if g(V, 'note_ok').lower() == 'true':
                pset(V, p, 'noted', 'yes')
            else:
                f = int(num(pg(V, p, 'note_fails'), 0) or 0) + 1
                pset(V, p, 'note_fails', f)
                if f >= int(P['fail_max']):
                    pset(V, p, 'noted', 'failed')
                else:
                    V['note_ok'] = 'pending'
                    V['route'] = 'note'
                    return
        note_next(V)
    def enter_wrapup(V):
        rec = [p for p in pids(V) if state(V, p) == 'recorded']
        bad = [p for p in pids(V) if state(V, p) == 'service_error']
        if multi(V) and (len(rec) > 1 or bad):
            line = T('recorded_many', list=T('and').join([pg(V, p, 'words') for p in rec]))
        else:
            line = T('recorded')
        parts = [line] + [T('rec_failed', words=pg(V, p, 'words')) for p in bad]
        if P['after_recorded']:
            parts.append(T('after_recorded'))
        parts.append(T('anything_else'))
        V['wrap_line'] = join(parts)
        V[P['outcome_var']] = P['promise_outcome']
        V[P['reason_var']] = ''
        V['route'] = 'wrapup'
    def finalize(V):
        ids = pids(V)
        sts = [state(V, p) for p in ids]
        fk = P['fin_keys']
        if 'recorded' in sts:
            key = fk['promise']
        elif sts and all(s == 'paid' for s in sts):
            key = fk['paid']
        else:
            key = fk['default']
            for s in sts:
                if s != 'paid':
                    key = fk.get(s) or fk['default']
                    break
        V['final_route'] = key
        V['route'] = 'fin'
    def ev_wrap_human(V):
        c = int(num(g(V, 'wrap_human'), 0) or 0) + 1
        V['wrap_human'] = str(c)
        if c >= int(P['human_limit']):
            V['route'] = 'xfer_general'
            return
        V['wrap_line'] = T('human_first')
        V['route'] = 'wrapup'
    def ev_wrap_change(V):
        c = int(num(g(V, 'wrap_count'), 0) or 0) + 1
        V['wrap_count'] = str(c)
        if c > int(P['wrap_turns']):
            finalize(V)
            return
        V['wrap_line'] = join([T('wrap_change'), T('anything_else')])
        V['route'] = 'wrapup'
    def ev_finalize(V):
        finalize(V)
    def state_line(V):
        ids = pids(V)
        out = []
        cur = g(V, 'cur_pid')
        for i, p in enumerate(ids):
            st = state(V, p)
            L = ladder(V, p)
            head = ('Product ' + str(i + 1) + ' of ' + str(len(ids)) + ': ') if len(ids) > 1 else 'Product: '
            s = head + pg(V, p, 'words') + ' (id ' + p + '). Past due ' + fmt(full_of(V, p)) + ', lowest amount ' + fmt(floor_of(V, p)) + ', latest date ' + txt_short(deadline_of(V, p)) + '.'
            if st == 'open':
                rl = refused_list(V, p)
                if rl:
                    s += ' Offers already refused: ' + ', '.join([x.replace('@', ' on ') for x in rl]) + ': never offer them again.'
                s += ' Persuasion attempts used: ' + pg(V, p, 'attempts_used', '0') + ' of ' + str(len(L)) + '.'
                if pg(V, p, 'offered_floor') == 'yes':
                    s += ' The lowest amount was already offered once: do not offer it again yourself.'
            elif st == 'agreed':
                s += ' Agreed, not recorded yet: ' + pg(V, p, 'agreed').split('|')[0] + ' on ' + (pg(V, p, 'agreed').split('|') + ['', ''])[1] + '.'
            else:
                s += ' Settled: ' + st + '.'
            out.append(s)
        if g(V, 'mode') == 'hardship':
            out.append('The customer mentioned a hardship: make no persuasion attempt and propose nothing yourself.')
        elif g(V, 'offer_question'):
            out.append('Current offer, ask exactly this: "' + g(V, 'offer_question') + '"')
        rec = [p for p in ids if state(V, p) == 'recorded']
        out.append('Recorded: ' + (', '.join(rec) if rec else 'nothing yet') + '.')
        V['state_line'] = ' '.join(out)
    def _clear_enums(V):
        for k, v in P['clear_enums'].items():
            V[k] = v
    def _clear_values(V):
        for k, v in P['clear_values'].items():
            V[k] = v
    def finish_turn(V):
        # an aside (a side question in the customer's turn: robot? scam?) is answered first, in the line the route speaks;
        # a turn that goes through code into a tts line never reaches the dialogue model, so the answer must be built here
        a = str(V.get('aside') or 'none')
        asides = P.get('asides') or {}
        if a != 'none' and a in asides:
            txt = str(asides[a].get('say') or '')
            key = {'confirm': 'readback_line', 'wrapup': 'wrap_line'}.get(str(V.get('route') or ''), 'say_next')
            line = str(V.get(key) or '')
            if txt and not line.startswith(txt):
                V[key] = (txt + ' ' + line).strip()
        _clear_enums(V)
        _clear_values(V)
        state_line(V)
    def main(V, ev):
        try:
            V['policy_event'] = ev
            V['offer_verdict'] = ''
            if ev == 'offer':
                ev_offer(V)
            elif ev == 'accept':
                ev_accept(V)
            elif ev == 'refuse':
                ev_refuse(V)
            elif ev == 'too_much':
                ev_too_much(V)
            elif ev in ('paid', 'dispute'):
                ev_settle(V, ev)
            elif ev == 'human':
                ev_human(V)
            elif ev == 'notalk':
                ev_notalk(V)
            elif ev == 'hardship':
                ev_hardship(V)
            elif ev == 'hs_decline':
                ev_hs_decline(V)
            elif ev == 'confirm_no':
                ev_confirm_no(V)
            elif ev == 'change':
                ev_change(V)
            elif ev == 'confirm_yes':
                ev_confirm_yes(V)
            elif ev == 'rec_after':
                ev_rec_after(V)
            elif ev == 'note_after':
                ev_note_after(V)
            elif ev == 'wrap_human':
                ev_wrap_human(V)
            elif ev == 'wrap_change':
                ev_wrap_change(V)
            elif ev == 'finalize':
                ev_finalize(V)
            V['policy_state'] = 'ok'
        except Exception as e:
            V['policy_state'] = 'error ' + ev + ': ' + str(e)
            if not g(V, 'route'):
                V['route'] = 'negotiate'
        try:
            finish_turn(V)
        except Exception as e:
            V['policy_state'] = 'error state_line: ' + str(e)
            V.setdefault('state_line', '')

    CB_RULE = {'open': '10:00', 'close': '19:00', 'same_day': True, 'later_than_now': True, 'days_ahead_business': 1, 'text': 'both included'}
    vars['cb_route'] = 'ask'
    nowdt = datetime.datetime.fromisoformat(str(vars.get('now') or '2000-01-01T00:00'))
    today = nowdt.date()
    status = str(vars.get('tp_status') or 'none')
    if status in ('wrong_number', 'deceased', 'unavailable'):
        vars['cb_route'] = status
    else:
        words = str(vars.get('cb_when') or '')
        tm = str(vars.get('cb_time') or '')
        if words:
            d, vague = resolve_when(vars, words)
            vars['cb_pending_date'] = d.isoformat() if d else words
        if tm:
            vars['cb_pending_time'] = tm
        dw = str(vars.get('cb_pending_date') or '')
        tw = str(vars.get('cb_pending_time') or '')
        if dw and tw:
            try:
                d = datetime.date.fromisoformat(dw)
                h, m = map(int, tw.split(':'))
                at = datetime.datetime.combine(d, datetime.time(h, m))
                allowed_days = [addbd(today, CB_RULE['days_ahead_business'])]
                if CB_RULE['same_day']:
                    allowed_days.append(today)
                valid = d in allowed_days and CB_RULE['open'] <= tw <= CB_RULE['close'] and at > nowdt
            except Exception:
                valid = False
            if valid:
                vars['cb_date_value'], vars['cb_time_value'] = dw, tw
                vars['cb_route'] = 'book'
            else:
                n = int(float(vars.get('cb_invalid') or 0)) + 1
                vars['cb_invalid'] = str(n)
                vars['cb_pending_date'] = ''
                vars['cb_pending_time'] = ''
                vars['cb_route'] = 'unavailable' if n >= 2 else 'retry'
        vars['cb_when'], vars['cb_time'], vars['tp_status'] = '', '', 'none'
    vars['cb_state'] = 'ok'
except Exception as e:
    vars['cb_state'] = 'error ' + str(e)
    vars.setdefault('cb_route', 'unavailable')

pre_actions.pre_process_code:
def _nz_main(config, vars):
    import re, json, datetime
    FIELDS = {'amount': 'amount', 'date': 'date'}
    ORDER = 'dmy'
    NOW_VAR = 'now'
    REL_VAR = ''
    PM_HOURS = (1, 2, 3, 4, 5, 6, 7)
    UNITS = dict(zero=0, oh=0, o=0, nought=0, nil=0, one=1, two=2, three=3, four=4, five=5, six=6, seven=7,
                 eight=8, nine=9)
    TEENS = dict(ten=10, eleven=11, twelve=12, thirteen=13, fourteen=14, fifteen=15, sixteen=16, seventeen=17,
                 eighteen=18, nineteen=19)
    TENS = dict(twenty=20, thirty=30, forty=40, fourty=40, fifty=50, sixty=60, seventy=70, eighty=80, ninety=90)
    ORD = dict(first=1, second=2, third=3, fourth=4, fifth=5, sixth=6, seventh=7, eighth=8, ninth=9, tenth=10,
               eleventh=11, twelfth=12, thirteenth=13, fourteenth=14, fifteenth=15, sixteenth=16,
               seventeenth=17, eighteenth=18, nineteenth=19, twentieth=20, thirtieth=30)
    SCALES = dict(hundred=100, thousand=1000, million=1000000)
    MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september',
              'october', 'november', 'december']
    WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
    CURRENCY = set(['dollar', 'dollars', 'pound', 'pounds', 'euro', 'euros', 'bucks', 'usd', 'eur', 'gbp',
                    'quid', 'rupees', 'francs'])
    FILLER = set(['um', 'umm', 'uh', 'uhh', 'er', 'erm', 'hmm', 'ah', 'well', 'so', 'ok', 'okay', 'yes', 'yeah',
                  'yep', 'sure', 'right', 'it', 'its', 'is', 'thats', 'that', 'my', 'the', 'are', 'was', 'were',
                  'then', 'and', 'i', 'think', 'believe', 'let', 'me', 'see', 'like', 'number', 'numbers',
                  'digit', 'digits', 'ends', 'ending', 'in', 'with', 'of', 'on', 'at', 'about', 'around',
                  'just', 'please', 'be', 'would', 'will', 'can', 'pay', 'say', 'lets', 'date', 'born', 'year',
                  'amount', 'time', 'by', 'for', 'a', 'an', 'exactly', 'only', 'now', 'here', 'there'])
    MARKERS = set(['no', 'sorry', 'actually', 'wait', 'correction', 'rather', 'nope', 'oops'])

    def clean(s, keep):
        s = str(s).lower().replace('’', "'")
        s = re.sub(r'\b([ap])\.\s?m\.?', r'\1m', s)
        s = s.replace("o'clock", ' oclock').replace("'", '')
        s = re.sub(r'(?<=[a-z])-(?=[a-z])', ' ', s)
        s = re.sub(r'(\d)(st|nd|rd|th)\b', r'\1', s)
        out = []
        for i, ch in enumerate(s):
            if ch.isalnum() or ch == ' ':
                out.append(ch)
            elif ch in keep and 0 < i < len(s) - 1 and s[i - 1].isdigit() and s[i + 1].isdigit():
                out.append(ch)
            else:
                out.append(' ')
        s = ''.join(out)
        s = re.sub(r'\bi mean\b|\bmake that\b|\bscratch that\b|\bor rather\b', ' sorry ', s)
        return s.split()

    def latest(toks):
        idx = -1
        for i, t in enumerate(toks):
            if t in MARKERS:
                idx = i
        if idx < 0:
            return toks
        after = [t for t in toks[idx + 1:] if t not in MARKERS]
        if [t for t in after if t not in FILLER]:
            return after
        return [t for t in toks[:idx] if t not in MARKERS]

    def expand(toks):
        out = []
        i = 0
        while i < len(toks):
            t = toks[i]
            if t in ('double', 'triple') and i + 1 < len(toks) and (toks[i + 1] in UNITS or re.fullmatch(r'\d', toks[i + 1])):
                out += [toks[i + 1]] * (2 if t == 'double' else 3)
                i += 2
                continue
            out.append(t)
            i += 1
        return out

    def is_num_word(t):
        return t in UNITS or t in TEENS or t in TENS or t in ORD or t in SCALES or bool(re.fullmatch(r'\d+', t))

    def segments(toks, amount=False):
        # A run of number words split into the groups a speaker says: "forty four seventy one" -> 44 | 71,
        # "four hundred and twenty" -> 420. Returns a list of [string, value, scaled] or None when a word is
        # neither a number nor a filler.
        segs = []
        cur = None
        n = len(toks)
        for i in range(n):
            t = toks[i]
            prev = toks[i - 1] if i else ''
            nxt = toks[i + 1] if i + 1 < n else ''
            if t in ('oh', 'o') and not (is_num_word(prev) or is_num_word(nxt)):
                continue
            if t == 'a' and nxt in SCALES:
                cur = dict(total=0, group=1, small=1, last='unit', scaled=False, lit=None)
                segs.append(cur)
                continue
            if re.fullmatch(r'\d+', t):
                v = int(t)
                cur = dict(total=0, group=v, small=v if v < 100 else 0, last='lit' if v >= 100 or not amount else 'unit',
                           scaled=False, lit=t)
                segs.append(cur)
                continue
            if t in UNITS or (t in ORD and ORD[t] < 10):
                u = UNITS[t] if t in UNITS else ORD[t]
                if u > 0 and cur is not None and cur['last'] in ('tens', 'scale'):
                    cur['group'] += u
                    cur['small'] += u
                    cur['last'] = 'unit'
                    cur['lit'] = None
                else:
                    cur = dict(total=0, group=u, small=u, last='unit', scaled=False, lit=None)
                    segs.append(cur)
                continue
            if t in TEENS or t in TENS or t in ORD:
                v = TEENS.get(t) or TENS.get(t) or ORD.get(t)
                kind = 'tens' if (t in TENS or v in (20, 30)) else 'teen'
                if cur is not None and cur['last'] == 'scale':
                    cur['group'] += v
                    cur['small'] += v
                    cur['last'] = kind
                    cur['lit'] = None
                else:
                    cur = dict(total=0, group=v, small=v, last=kind, scaled=False, lit=None)
                    segs.append(cur)
                continue
            if t in SCALES:
                m = SCALES[t]
                if cur is None or cur['last'] == 'scale':
                    return None
                if m == 100:
                    if cur['group'] != cur['small'] or cur['small'] == 0:
                        return None
                    cur['group'] = cur['small'] * 100
                else:
                    if cur['group'] == 0:
                        return None
                    cur['total'] += cur['group'] * m
                    cur['group'] = 0
                cur['small'] = 0
                cur['last'] = 'scale'
                cur['scaled'] = True
                cur['lit'] = None
                continue
            if t in FILLER or t in CURRENCY:
                continue
            return None
        out = []
        for c in segs:
            v = c['total'] + c['group']
            out.append([c['lit'] if c['lit'] is not None else str(v), v, c['scaled']])
        return out

    def to_digits(v):
        s = str(v).strip()
        if re.fullmatch(r'\d+', s):
            return s
        s = re.sub(r'\blast\s+(?:\w+\s+)?(?:digits?|numbers?)\b', ' ', s.lower())
        s = re.sub(r'\blast\s+(?:two|three|four|five|six|2|3|4|5|6)\b', ' ', s)
        toks = clean(s, '')
        toks = expand(latest(toks))
        segs = segments(toks)
        if not segs:
            return None
        r = ''.join(x[0] for x in segs)
        return r if re.fullmatch(r'\d+', r) else None

    def now_date():
        try:
            raw = str(vars.get(NOW_VAR) or '').strip()
            return datetime.date.fromisoformat(raw[:10]) if raw else None
        except Exception:
            return None

    def mkdate(y, m, d):
        try:
            return datetime.date(int(y), int(m), int(d))
        except Exception:
            return None

    def year_of(ys, past):
        if re.fullmatch(r'\d{4}', ys):
            return int(ys)
        if not re.fullmatch(r'\d{2}', ys):
            return None
        today = now_date()
        if today is None:
            return None
        yy = int(ys)
        if past:
            y = 2000 + yy
            return y if y <= today.year else 1900 + yy
        cands = [1900 + yy, 2000 + yy, 2100 + yy]
        cands.sort(key=lambda c: abs(c - today.year))
        return cands[0]

    def relative(toks):
        if not REL_VAR:
            return None
        table = vars.get(REL_VAR)
        if isinstance(table, str):
            try:
                table = json.loads(table)
            except Exception:
                return None
        if not isinstance(table, dict):
            return None
        words = [t for t in toks if t not in ('on', 'the', 'um', 'uh', 'er', 'erm', 'please', 'by', 'lets', 'say')]
        key = ' '.join(words)
        r = table.get(key)
        if isinstance(r, str) and re.fullmatch(r'\d{4}-\d{2}-\d{2}', r):
            return r
        return None

    def to_date(v, past):
        s = str(v).strip()
        m = re.fullmatch(r'(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[t ].*)?', s.lower())
        if m:
            d = mkdate(m.group(1), m.group(2), m.group(3))
            return d.isoformat() if d else None
        toks = latest(clean(s, '/.-'))
        if not toks:
            return None
        r = relative(toks)
        if r:
            return r
        toks = [t for t in toks if t not in WEEKDAYS]
        mon = []
        for i, t in enumerate(toks):
            for k, name in enumerate(MONTHS):
                if t == name or t == name[:3] or (t == 'sept' and k == 8):
                    mon.append((i, k + 1))
                    break
        if len(mon) > 1:
            return None
        if mon:
            i, month = mon[0]
            before = segments(toks[:i])
            after = segments(toks[i + 1:])
            if before is None or after is None:
                return None
            if before:
                if len(before) != 1:
                    return None
                day = before[0][1]
                yparts = after
            else:
                if not after:
                    return None
                day = after[0][1]
                yparts = after[1:]
            if yparts:
                y = year_of(''.join(x[0] for x in yparts), past)
                if y is None:
                    return None
                d = mkdate(y, month, day)
                return d.isoformat() if d else None
            if past:
                return None
            today = now_date()
            if today is None:
                return None
            d = mkdate(today.year, month, day)
            if d is not None and d < today:
                d = mkdate(today.year + 1, month, day)
            return d.isoformat() if d else None
        joined = ' '.join(toks)
        m = re.fullmatch(r'(\d{1,2})[/.\- ](\d{1,2})[/.\- ](\d{2}|\d{4})', joined)
        if m:
            a, b, ys = int(m.group(1)), int(m.group(2)), m.group(3)
        else:
            m8 = re.fullmatch(r'\d{8}', joined)
            if m8:
                if joined[:2] in ('19', '20'):
                    d = mkdate(joined[:4], joined[4:6], joined[6:])
                    if d:
                        return d.isoformat()
                a, b, ys = int(joined[:2]), int(joined[2:4]), joined[4:]
            else:
                segs = segments(toks)
                if not segs or len(segs) < 3 or segs[0][2] or segs[1][2] or segs[0][1] == 0 or segs[1][1] == 0:
                    return None
                a, b = segs[0][1], segs[1][1]
                ys = ''.join(x[0] for x in segs[2:])
        y = year_of(ys, past)
        if y is None:
            return None
        day, month = (a, b) if ORDER == 'dmy' else (b, a)
        d = mkdate(y, month, day)
        if d is None:
            d = mkdate(y, day, month)
        return d.isoformat() if d else None

    def to_amount(v):
        if isinstance(v, bool):
            return None
        if isinstance(v, (int, float)):
            return float(v)
        s = str(v).strip().lower()
        cents = 0.0
        m = re.fullmatch(r'(.*?)\s*(?:dollars?|pounds?|euros?|bucks)\s*(?:and\s+)?(.+?)\s*(?:cents?|pence)', s)
        if m:
            c = to_amount(m.group(2))
            if c is None or c >= 100:
                return None
            cents = c / 100.0
            s = m.group(1)
        s = re.sub(r'[$£€]', ' ', s)
        toks = latest(clean(s, ',.'))
        toks = [t for t in toks if t not in CURRENCY]
        mult = 1.0
        if toks and re.fullmatch(r'[\d.,]+k', toks[-1]):
            toks[-1] = toks[-1][:-1]
            mult = 1000.0
        elif len(toks) >= 2 and toks[-1] == 'k':
            toks = toks[:-1]
            mult = 1000.0
        if len(toks) == 1 and re.fullmatch(r'\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?|\.\d+', toks[0]):
            return round(float(toks[0].replace(',', '')) * mult + cents, 2)
        dec = ''
        if 'point' in toks:
            k = toks.index('point')
            dd = to_digits(' '.join(toks[k + 1:]))
            if not dd:
                return None
            dec = '.' + dd
            toks = toks[:k]
        segs = segments(toks, amount=True)
        if segs == [] and dec:
            segs = [['0', 0, False]]
        if not segs:
            return None
        if len(segs) == 1:
            whole = segs[0][1]
        elif len(segs) == 2 and not segs[0][2] and not segs[1][2] and segs[0][1] < 100 and 10 <= segs[1][1] < 100 and segs[0][0].isdigit() and len(segs[0][0]) <= 2:
            whole = segs[0][1] * 100 + segs[1][1]
        elif len(segs) == 3 and not any(x[2] for x in segs) and 0 < segs[0][1] < 100 and segs[1][1] == 0 and segs[1][0] == '0' and segs[2][1] < 10:
            whole = segs[0][1] * 100 + segs[2][1]
        else:
            return None
        return round(float(str(whole) + dec) * mult + cents, 2)

    def to_time(v):
        s = str(v).strip().lower()
        if re.fullmatch(r'\d{2}:\d{2}', s):
            return s if int(s[:2]) < 24 and int(s[3:]) < 60 else None
        s = re.sub(r'(\d)\s*([ap])\.?\s?m\b\.?', r'\1 \2m', s)
        toks = latest(clean(s, ':.'))
        txt = ' ' + ' '.join(toks) + ' '
        mer = ''
        if re.search(r' (am|in the morning|morning) ', txt):
            mer = 'am'
        if re.search(r' (pm|in the afternoon|afternoon|in the evening|evening|at night|tonight) ', txt):
            mer = 'pm' if not mer else 'x'
        if mer == 'x':
            return None
        txt = re.sub(r' (am|pm|in the morning|in the afternoon|in the evening|at night|morning|afternoon|evening|tonight|oclock|minutes|mins|hours|hrs|sharp) ', ' ', txt)
        txt = re.sub(r' (am|pm|in the morning|in the afternoon|in the evening|at night|morning|afternoon|evening|tonight|oclock|minutes|mins|hours|hrs|sharp) ', ' ', txt)
        toks = [t for t in txt.split() if t not in ('at', 'about', 'around', 'say', 'lets', 'the', 'by', 'um', 'uh', 'er', 'erm', 'please', 'maybe')]
        if toks in (['noon'], ['midday']):
            return '12:00'
        if toks == ['midnight']:
            return '00:00'
        h = mi = None

        def num(ws):
            if len(ws) == 1 and re.fullmatch(r'\d{1,2}', ws[0]):
                return int(ws[0])
            if ws == ['half']:
                return 30
            if ws in (['quarter'], ['a', 'quarter']):
                return 15
            sg = segments(ws)
            if sg and len(sg) == 1 and not sg[0][2]:
                return sg[0][1]
            if sg and len(sg) == 2 and sg[0][1] == 0 and sg[1][1] < 10:
                return sg[1][1]
            return None
        for rel in ('past', 'after', 'to', 'before', 'till', 'til'):
            if rel in toks:
                k = toks.index(rel)
                a, b = num(toks[:k]), num(toks[k + 1:])
                if a is None or b is None or a >= 60:
                    return None
                if rel in ('past', 'after'):
                    h, mi = b, a
                else:
                    h, mi = b - 1, 60 - a
                    if h < 0:
                        h = 23
                break
        if h is None:
            if len(toks) == 1 and re.fullmatch(r'\d{1,2}[:.]\d{2}', toks[0]):
                h, mi = int(toks[0][:-3]), int(toks[0][-2:])
            elif len(toks) == 1 and re.fullmatch(r'\d{1,2}', toks[0]):
                h, mi = int(toks[0]), 0
            elif len(toks) == 2 and all(re.fullmatch(r'\d{1,2}', t) for t in toks):
                h, mi = int(toks[0]), int(toks[1])
            else:
                sg = segments(toks)
                if not sg or any(x[2] for x in sg):
                    return None
                if len(sg) == 1:
                    h, mi = sg[0][1], 0
                elif len(sg) == 2:
                    h, mi = sg[0][1], sg[1][1]
                elif len(sg) == 3 and sg[1][1] == 0 and sg[2][1] < 10:
                    h, mi = sg[0][1], sg[2][1]
                else:
                    return None
        if h is None or mi is None or not (0 <= mi < 60) or not (0 <= h < 24):
            return None
        if mer == 'pm' and h < 12:
            h += 12
        elif mer == 'am' and h == 12:
            h = 0
        elif mer == 'am' and h > 12:
            return None
        elif not mer and h in PM_HOURS:
            h += 12
        return '%02d:%02d' % (h, mi)

    def kind_for(name, kind, body):
        if kind != 'answer':
            return kind
        f = str(body.get('field') or body.get('question') or '').lower()
        if re.search(r'date|birth|dob', f):
            return 'dob'
        if f:
            return 'digits'
        return 'answer'

    body = config.get('body') if isinstance(config, dict) else None
    if not isinstance(body, dict):
        return
    for name in FIELDS:
        try:
            if name not in body:
                continue
            val = body.get(name)
            if val is None or (isinstance(val, str) and not val.strip()):
                continue
            kind = kind_for(name, FIELDS[name], body)
            new = None
            if kind == 'amount':
                new = to_amount(val)
            elif isinstance(val, (int, float)) and not isinstance(val, bool):
                continue
            elif kind == 'digits':
                new = to_digits(val)
            elif kind in ('date', 'dob'):
                new = to_date(val, kind == 'dob')
            elif kind == 'time':
                new = to_time(val)
            else:
                new = to_date(val, True)
                if new is None:
                    new = to_digits(val)
            if new is not None:
                body[name] = new
        except Exception:
            pass


